1: <#
2: .SYNOPSIS
3:     SessionStart hook: one line saying which reviewers are usable right now.
4: 
5: .DESCRIPTION
6:     Runs at the start of a Claude Code session in any project where the plugin is
7:     enabled (hooks/hooks.json). Prints ONE line to stdout, which Claude Code adds to the
8:     agent's context:
9: 
10:         codex-consult: reviewers - openai available | ZAI available | mimo unavailable
11:         (missing: env MIMO_API_KEY not set); roster -> would select ZAI
12: 
13:     or, when the Codex CLI is not on PATH, `codex-consult: codex CLI not found on PATH -
14:     follow the setup-providers skill`. Everything else (an unreadable config, an unusable
15:     roster, a crash inside the check) is reported in the same one-line form and never
16:     fails the session: the exit code is always 0. No network call, no lock, nothing
17:     written: it runs `codex-providers.ps1 -Json -NoNetwork` - the same local check
18:     codex-providers.ps1 makes (credentials, table usability, endpoint health from THIS
19:     repository's ledgers, the roster walk), except that the sign-in of an engine provider
20:     (the agy engine's `agy models`, a network round-trip) is NOT checked here: such a row
21:     reads e.g. `gemini not checked (launcher present)` (a missing launcher stays
22:     `gemini unavailable (agy CLI not found on PATH)`; a recorded auth failure or usage
23:     limit still shows), and the roster walk skips it - unless THIS repository's ledgers
24:     hold a usable reply on that engine's endpoint from the last 60 minutes, which evidences
25:     the sign-in without any call (`gemini available`). `codex-providers.ps1` without
26:     -NoNetwork and the consultation's own preflight do check it. The muse engine's sign-in
27:     check (wave 23) reads ~/.config/muse/auth.json locally and so runs here too (`meta
28:     available`), as does its billing guard (`meta unavailable (refused: META_API_KEY is
29:     set: ...)`).
30: 
31:     Cost: about one second (`codex login status` for the built-in openai), once per
32:     session. Disable the hook by disabling the plugin's hooks in Claude Code settings.
33: 
34:     Runs on Windows PowerShell 5.1 and PowerShell 7.
35: #>
36: [CmdletBinding()]
37: param(
38:     # Where consultations are stored (endpoint health is read from every task ledger
39:     # under it). Relative paths resolve against the git repo root of the current directory.
40:     [string]$CollabDir = '.collab'
41: )
42: 
43: $ErrorActionPreference = 'Stop'
44: $line = ''
45: try {
46:     $providers = Join-Path $PSScriptRoot 'codex-providers.ps1'
47:     $psExe = (Get-Process -Id $PID).Path
48:     $codex = Get-Command codex -ErrorAction SilentlyContinue
49:     if (-not $codex) {
50:         $line = 'codex-consult: codex CLI not found on PATH - follow the setup-providers skill before consulting a reviewer'
51:     } else {
52:         $previous = $ErrorActionPreference
53:         $ErrorActionPreference = 'Continue'
54:         $raw = & $psExe -NoProfile -ExecutionPolicy Bypass -File $providers -Json -NoNetwork -CollabDir $CollabDir 2>&1 | ForEach-Object { "$_" }
55:         $code = $LASTEXITCODE
56:         $ErrorActionPreference = $previous
57:         $jsonStart = -1
58:         for ($i = 0; $i -lt $raw.Count; $i++) { if ($raw[$i] -match '^\s*\[') { $jsonStart = $i; break } }
59:         if ($jsonStart -lt 0) {
60:             $first = (@($raw | Where-Object { $_ -and $_.Trim() }) | Select-Object -First 1)
61:             if (-not $first) { $first = "codex-providers.ps1 exited $code without output" }
62:             $line = "codex-consult: reviewer check failed - $first"
63:         } else {
64:             # Pipeline form on purpose: on Windows PowerShell 5.1 `ConvertFrom-Json -InputObject`
65:             # hands a JSON array back as ONE object, which @() would not unroll.
66:             $jsonText = ($raw[$jsonStart..($raw.Count - 1)]) -join "`n"
67:             $rows = @()
68:             foreach ($item in ($jsonText | ConvertFrom-Json)) { $rows += $item }
69:             $parts = New-Object System.Collections.Generic.List[string]
70:             $selected = ''
71:             foreach ($r in $rows) {
72:                 $verdict = [string]$r.verdict
73:                 $short = $verdict
74:                 if ($verdict -match '^(available|unavailable|unknown)\s*(\((.*)\))?$') {
75:                     $short = $Matches[1]
76:                     if ($Matches[3]) {
77:                         $reason = $Matches[3]
78:                         if ($reason.Length -gt 60) { $reason = $reason.Substring(0, 57) + '...' }
79:                         $short += " ($reason)"
80:                     }
81:                 }
82:                 # an engine row whose sign-in was not checked (-NoNetwork): say so plainly
83:                 $rowEngine = [string]$r.engine
84:                 if ($rowEngine -and $rowEngine -ne 'codex' -and ([string]$r.credentials).StartsWith('not checked') -and $verdict -like 'unknown*') { $short = 'not checked (launcher present)' }
85:                 $parts.Add("$($r.name) $short")
86:                 if ($r.roster_selected -eq $true) { $selected = [string]$r.name }
87:             }
88:             $line = 'codex-consult: reviewers - ' + ($parts.ToArray() -join ' | ')
89:             if ($selected) { $line += "; roster -> would select $selected" }
90:             elseif (@($rows | Where-Object { $null -ne $_.roster_position }).Count -gt 0) { $line += '; roster -> no entry is available' }
91:         }
92:     }
93: } catch {
94:     $msg = ("$($_.Exception.Message)" -replace '\s+', ' ').Trim()
95:     if ($msg.Length -gt 120) { $msg = $msg.Substring(0, 117) + '...' }
96:     $line = "codex-consult: reviewer check failed - $msg"
97: }
98: Write-Output $line
99: exit 0
{
  "hooks": {
    "SessionStart": [
      {
        "matcher": "startup|resume",
        "hooks": [
          {
            "type": "command",
            "command": "if command -v pwsh >/dev/null 2>&1; then pwsh -NoProfile -File \"${CLAUDE_PLUGIN_ROOT}/scripts/codex-consult-hook.ps1\"; else powershell -NoProfile -ExecutionPolicy Bypass -File \"${CLAUDE_PLUGIN_ROOT}/scripts/codex-consult-hook.ps1\"; fi",
            "timeout": 30,
            "statusMessage": "codex-consult: checking which reviewers are usable"
          }
        ]
      }
    ]
  }
}

1: <#
2: .SYNOPSIS
3:     Usefulness telemetry: which reviewer was useful on which kind of question.
4: 
5: .DESCRIPTION
6:     Reads the ledgers (<CollabDir>/<task>/sessions.json) and findings stores
7:     (<CollabDir>/<task>/findings.json) of EVERY task of this repository, or of one task
8:     with -Task, and prints one row per (reviewer lineage, purpose), a total row per
9:     lineage and a grand total. Nothing is written, no lock is taken; a store that cannot
10:     be read is reported and left out. Exit 0.
11: 
12:     Row key
13:       REVIEWER   '<provider> :: <model>' of the consultation (its ledger reviewer), with
14:                  ' [<engine>]' appended for an engine other than codex (0.4.0, e.g.
15:                  'gemini :: gemini-3.8-flash-high [agy]'; an absent reviewer.engine is
16:                  codex); 'unknown provenance' for entries recorded before 0.3.0 (no reviewer)
17:       PURPOSE    the consultation's purpose, '(none)' without one; '(total)' on a
18:                  lineage's total row; the grand total row is '(all) (total)'
19:     Columns (JSON field in brackets)
20:       CONSULTS   ledger entries [consults]
21:       USABLE     bridge_outcome 'usable reply' [usable]
22:       PROSE      usable, but no valid structured reply (-Raw, chore, invalid JSON) [prose]
23:       FAILED     every other outcome [failed]
24:       RAISED     findings raised by these consultations (a finding belongs to the
25:                  consultation it was ingested from: source.consult = the entry's n, in
26:                  the same task - the join codex-findings.ps1 -Stats uses) [raised]
27:       VERIFIED / REJECTED / WONTFIX / SUPERSEDED   their current status [verified,
28:                  rejected, wontfix, superseded]
29:       OPEN       proposed + implemented [open]
30:       HIT%       verified / (verified + rejected), rounded percent; '-' when both are 0
31:                  [hit_rate: a number, or null]
32:       A/H/R/D    verdicts ACCEPT / HOLD / REJECT / ADVISE [verdict_accept, verdict_hold,
33:                  verdict_reject, verdict_advise]
34:       Y/P/N      the judge's usefulness marks (codex-findings.ps1 -Rate): yes / partly /
35:                  no [rated_yes, rated_partly, rated_no]
36:       MEDIAN_S   median wall_seconds; '-' when none [median_wall_seconds: number or null]
37:       TOKENS     input tokens not served from the cache / output tokens [tokens_in,
38:                  tokens_out]
39:     Findings whose consultation has no ledger entry count as 'unknown provenance' /
40:     '(none)'. Rows are sorted by lineage (case-insensitive; unknown provenance last),
41:     then purpose. -Json prints an array of the same rows with numeric fields (plus
42:     `kind`: purpose | lineage | total).
43: 
44: .EXAMPLE
45:     powershell -NoProfile -ExecutionPolicy Bypass -File codex-scoreboard.ps1
46: 
47: .EXAMPLE
48:     pwsh -NoProfile -File codex-scoreboard.ps1 -Task cache-rewrite -Json
49: #>
50: [CmdletBinding()]
51: param(
52:     # Where consultations are stored. Relative paths resolve against the git repo root.
53:     [string]$CollabDir = '.collab',
54: 
55:     # One task only (its directory under <CollabDir>).
56:     [string]$Task = '',
57: 
58:     # An array of row objects instead of the table.
59:     [switch]$Json
60: )
61: 
62: $ErrorActionPreference = 'Stop'
63: $script:ToolName = 'codex-scoreboard'
64: . (Join-Path $PSScriptRoot 'codex-consult-common.ps1')
65: 
66: if ($Task -and $Task -notmatch '^[A-Za-z0-9][A-Za-z0-9._-]*$') {
67:     Stop-WithError "-Task must be a slug (letters, digits, dot, dash, underscore)."
68: }
69: $repoRoot = Resolve-RepoRoot -Cwd (Get-Location).Path
70: $collabRoot = Resolve-CollabRoot -RepoRoot $repoRoot -CollabDir $CollabDir
71: 
72: $taskDirs = @()
73: if ($Task) {
74:     $one = Join-Path $collabRoot $Task
75:     if (-not (Test-Path -LiteralPath $one -PathType Container)) { Stop-WithError "no task '$Task' under $collabRoot." }
76:     $taskDirs = @(Get-Item -LiteralPath $one)
77: } elseif (Test-Path -LiteralPath $collabRoot -PathType Container) {
78:     $taskDirs = @(Get-ChildItem -LiteralPath $collabRoot -Directory | Sort-Object Name)
79: }
80: 
81: # Tolerant reads: a store that does not parse is reported and left out.
82: $notes = New-Object System.Collections.Generic.List[string]
83: function Read-TolerantStore {
84:     param([string]$Path)
85:     if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $null }
86:     try { return (ConvertFrom-JsonKeepOffset -Text (Read-SharedText -Path $Path)) } catch {
87:         $notes.Add("left out: $Path does not parse ($(ConvertTo-OneLine $_.Exception.Message))")
88:         return $null
89:     }
90: }
91: 
92: function Get-IntValue {
93:     param($Object, [string]$Name)
94:     $v = Get-PropertyValue $Object $Name $null
95:     $n = [long]0
96:     if ($null -ne $v -and [long]::TryParse([string]$v, [ref]$n)) { return $n }
97:     return $null
98: }
99: 
100: # One accumulator per row key.
101: $rows = @{}
102: function Get-Acc {
103:     param([string]$Lineage, [string]$Purpose)
104:     $key = "$Lineage`t$Purpose"
105:     if (-not $rows.ContainsKey($key)) {
106:         $rows[$key] = [pscustomobject]@{
107:             Lineage = $Lineage; Purpose = $Purpose; Consults = 0; Usable = 0; Prose = 0; Failed = 0
108:             Raised = 0; Verified = 0; Rejected = 0; Wontfix = 0; Superseded = 0; Open = 0
109:             Accept = 0; Hold = 0; Reject = 0; Advise = 0; Yes = 0; Partly = 0; No = 0
110:             Walls = (New-Object System.Collections.Generic.List[double]); TokensIn = [long]0; TokensOut = [long]0
111:         }
112:     }
113:     return $rows[$key]
114: }
115: 
116: foreach ($dir in $taskDirs) {
117:     $sessions = Read-TolerantStore -Path (Join-Path $dir.FullName 'sessions.json')
118:     $store = Read-TolerantStore -Path (Join-Path $dir.FullName 'findings.json')
119:     $keyOf = @{}
120:     foreach ($c in @(Get-PropertyValue (Get-PropertyValue $sessions 'codex' $null) 'consults' @())) {
121:         if ($null -eq $c) { continue }
122:         $rev = Get-PropertyValue $c 'reviewer' $null
123:         $lineage = 'unknown provenance'
124:         if ($null -ne $rev) { $lineage = Format-ReviewerLineage -Provider ([string](Get-PropertyValue $rev 'provider' '')) -Model ([string](Get-PropertyValue $rev 'model' '')) -Engine ([string](Get-PropertyValue $rev 'engine' '')) }
125:         $purpose = [string](Get-PropertyValue $c 'purpose' '')
126:         if (-not $purpose) { $purpose = '(none)' }
127:         $acc = Get-Acc $lineage $purpose
128:         $n = Get-IntValue $c 'n'
129:         if ($null -ne $n) { $keyOf[$n] = $acc }
130:         $acc.Consults++
131:         $outcome = [string](Get-PropertyValue $c 'bridge_outcome' (Get-PropertyValue $c 'outcome' ''))
132:         if ($outcome -eq 'usable reply') {
133:             $acc.Usable++
134:             if ((Get-PropertyValue $c 'structured' $false) -ne $true) { $acc.Prose++ }
135:         } else {
136:             $acc.Failed++
137:         }
138:         switch ([string](Get-PropertyValue $c 'verdict' '')) {
139:             'ACCEPT' { $acc.Accept++ }
140:             'HOLD' { $acc.Hold++ }
141:             'REJECT' { $acc.Reject++ }
142:             'ADVISE' { $acc.Advise++ }
143:         }
144:         $wall = Get-PropertyValue $c 'wall_seconds' $null
145:         $w = [double]0
146:         if ($null -ne $wall -and [double]::TryParse([string]$wall, [System.Globalization.NumberStyles]::Float, $script:Invariant, [ref]$w)) { $acc.Walls.Add($w) }
147:         $usage = Get-PropertyValue $c 'usage' $null
148:         if ($null -ne $usage) {
149:             $in = Get-IntValue $usage 'input_tokens'
150:             $cached = Get-IntValue $usage 'cached_input_tokens'
151:             $out = Get-IntValue $usage 'output_tokens'
152:             if ($null -ne $in) { $acc.TokensIn += [Math]::Max([long]0, $in - $(if ($null -ne $cached) { $cached } else { 0 })) }
153:             if ($null -ne $out) { $acc.TokensOut += $out }
154:         }
155:     }
156:     foreach ($f in @(Get-PropertyValue $store 'findings' @())) {
157:         if ($null -eq $f) { continue }
158:         $n = Get-IntValue (Get-PropertyValue $f 'source' $null) 'consult'
159:         $acc = $null
160:         if ($null -ne $n -and $keyOf.ContainsKey($n)) { $acc = $keyOf[$n] } else { $acc = Get-Acc 'unknown provenance' '(none)' }
161:         $acc.Raised++
162:         switch ([string](Get-PropertyValue $f 'status' '')) {
163:             'verified' { $acc.Verified++ }
164:             'rejected' { $acc.Rejected++ }
165:             'wontfix' { $acc.Wontfix++ }
166:             'superseded' { $acc.Superseded++ }
167:             'proposed' { $acc.Open++ }
168:             'implemented' { $acc.Open++ }
169:         }
170:     }
171:     foreach ($rt in @(Get-PropertyValue $store 'ratings' @())) {
172:         if ($null -eq $rt) { continue }
173:         $n = Get-IntValue $rt 'n'
174:         $acc = $null
175:         if ($null -ne $n -and $keyOf.ContainsKey($n)) { $acc = $keyOf[$n] }
176:         else {
177:             $p = [string](Get-PropertyValue $rt 'purpose' '')
178:             $acc = Get-Acc ([string](Get-PropertyValue $rt 'lineage' 'unknown provenance')) $(if ($p) { $p } else { '(none)' })
179:         }
180:         switch ([string](Get-PropertyValue $rt 'useful' '')) {
181:             'yes' { $acc.Yes++ }
182:             'partly' { $acc.Partly++ }
183:             'no' { $acc.No++ }
184:         }
185:     }
186: }
187: 
188: function Get-Median {
189:     param([double[]]$Values)
190:     if ($Values.Count -eq 0) { return $null }
191:     $sorted = @($Values | Sort-Object)
192:     $mid = [int][Math]::Floor($sorted.Count / 2)
193:     if ($sorted.Count % 2 -eq 1) { return [double]$sorted[$mid] }
194:     return ([double]$sorted[$mid - 1] + [double]$sorted[$mid]) / 2
195: }
196: 
197: $counters = @('Consults', 'Usable', 'Prose', 'Failed', 'Raised', 'Verified', 'Rejected', 'Wontfix', 'Superseded', 'Open', 'Accept', 'Hold', 'Reject', 'Advise', 'Yes', 'Partly', 'No', 'TokensIn', 'TokensOut')
198: function New-OutRow {
199:     param([string]$Kind, [string]$Lineage, [string]$Purpose, [object[]]$Parts)
200:     $sum = @{}
201:     foreach ($k in $counters) { $sum[$k] = [long]0 }
202:     $walls = New-Object System.Collections.Generic.List[double]
203:     foreach ($a in $Parts) {
204:         foreach ($k in $counters) { $sum[$k] += [long]$a.$k }
205:         foreach ($w in $a.Walls) { $walls.Add($w) }
206:     }
207:     $hit = $null
208:     if (($sum.Verified + $sum.Rejected) -gt 0) { $hit = [int][Math]::Round(100.0 * $sum.Verified / ($sum.Verified + $sum.Rejected), [MidpointRounding]::AwayFromZero) }
209:     $median = Get-Median -Values ([double[]]$walls.ToArray())
210:     return [pscustomobject]@{
211:         kind                = $Kind
212:         lineage             = $Lineage
213:         purpose             = $Purpose
214:         consults            = $sum.Consults
215:         usable              = $sum.Usable
216:         prose               = $sum.Prose
217:         failed              = $sum.Failed
218:         raised              = $sum.Raised
219:         verified            = $sum.Verified
220:         rejected            = $sum.Rejected
221:         wontfix             = $sum.Wontfix
222:         superseded          = $sum.Superseded
223:         open                = $sum.Open
224:         hit_rate            = $hit
225:         verdict_accept      = $sum.Accept
226:         verdict_hold        = $sum.Hold
227:         verdict_reject      = $sum.Reject
228:         verdict_advise      = $sum.Advise
229:         rated_yes           = $sum.Yes
230:         rated_partly        = $sum.Partly
231:         rated_no            = $sum.No
232:         median_wall_seconds = $median
233:         tokens_in           = $sum.TokensIn
234:         tokens_out          = $sum.TokensOut
235:     }
236: }
237: 
238: $all = @($rows.Values)
239: $lineages = @($all | ForEach-Object { $_.Lineage } | Select-Object -Unique | Sort-Object @{ Expression = { $_ -eq 'unknown provenance' } }, @{ Expression = { $_.ToLowerInvariant() } })
240: $out = New-Object System.Collections.Generic.List[object]
241: foreach ($lin in $lineages) {
242:     $mine = @($all | Where-Object { $_.Lineage -eq $lin } | Sort-Object @{ Expression = { $_.Purpose.ToLowerInvariant() } })
243:     foreach ($a in $mine) { $out.Add((New-OutRow -Kind 'purpose' -Lineage $lin -Purpose $a.Purpose -Parts @($a))) }
244:     $out.Add((New-OutRow -Kind 'lineage' -Lineage $lin -Purpose '(total)' -Parts $mine))
245: }
246: if ($all.Count -gt 0) { $out.Add((New-OutRow -Kind 'total' -Lineage '(all)' -Purpose '(total)' -Parts $all)) }
247: 
248: if ($Json) {
249:     Write-Output (ConvertTo-Json -InputObject ([object[]]$out.ToArray()) -Depth 4)
250:     exit 0
251: }
252: 
253: Write-Host "codex-scoreboard: $collabRoot$(if ($Task) { " (task $Task)" } else { " ($($taskDirs.Count) task(s))" })"
254: foreach ($note in $notes) { Write-Host $note -ForegroundColor Yellow }
255: if ($out.Count -eq 0) {
256:     Write-Host 'no consultations recorded.'
257:     exit 0
258: }
259: $header = [ordered]@{ reviewer = 'REVIEWER'; purpose = 'PURPOSE'; consults = 'CONSULTS'; usable = 'USABLE'; prose = 'PROSE'; failed = 'FAILED'; raised = 'RAISED'; verified = 'VERIFIED'; rejected = 'REJECTED'; wontfix = 'WONTFIX'; superseded = 'SUPERSEDED'; open = 'OPEN'; hit = 'HIT%'; verdicts = 'A/H/R/D'; ratings = 'Y/P/N'; median = 'MEDIAN_S'; tokens = 'TOKENS' }
260: $lines = New-Object System.Collections.Generic.List[object]
261: $lines.Add([pscustomobject]$header)
262: foreach ($r in $out) {
263:     $lines.Add([pscustomobject][ordered]@{
264:             reviewer   = $r.lineage
265:             purpose    = $r.purpose
266:             consults   = [string]$r.consults
267:             usable     = [string]$r.usable
268:             prose      = [string]$r.prose
269:             failed     = [string]$r.failed
270:             raised     = [string]$r.raised
271:             verified   = [string]$r.verified
272:             rejected   = [string]$r.rejected
273:             wontfix    = [string]$r.wontfix
274:             superseded = [string]$r.superseded
275:             open       = [string]$r.open
276:             hit        = $(if ($null -eq $r.hit_rate) { '-' } else { "$($r.hit_rate)%" })
277:             verdicts   = "$($r.verdict_accept)/$($r.verdict_hold)/$($r.verdict_reject)/$($r.verdict_advise)"
278:             ratings    = "$($r.rated_yes)/$($r.rated_partly)/$($r.rated_no)"
279:             median     = $(if ($null -eq $r.median_wall_seconds) { '-' } else { ([double]$r.median_wall_seconds).ToString('0.#', $script:Invariant) })
280:             tokens     = "$($r.tokens_in)/$($r.tokens_out)"
281:         })
282: }
283: $cols = @($header.Keys)
284: $numeric = @('consults', 'usable', 'prose', 'failed', 'raised', 'verified', 'rejected', 'wontfix', 'superseded', 'open', 'hit', 'median')
285: $width = @{}
286: foreach ($col in $cols) { $width[$col] = (@($lines | ForEach-Object { ([string]$_.$col).Length }) | Measure-Object -Maximum).Maximum }
287: foreach ($l in $lines) {
288:     $parts = foreach ($col in $cols) { if ($numeric -contains $col) { ([string]$l.$col).PadLeft($width[$col]) } else { ([string]$l.$col).PadRight($width[$col]) } }
289:     Write-Host (($parts -join '  ').TrimEnd())
290: }
291: exit 0

1: # codex-consult parallel panel (0.4.x wave 21, ROADMAP R11, decisions D1-D13 of the parallel812:     }
813:     $order = @($jr | ForEach-Object { "$($_.lineage)|$($_.purpose)" }) -join ' ; '
814:     $badS = @()
815:     foreach ($k in $want.Keys) {
816:         $row = @($jr | Where-Object { "$($_.lineage)|$($_.purpose)" -eq $k }) | Select-Object -First 1
817:         if (-not $row) { $badS += "missing row $k"; continue }
818:         for ($i = 0; $i -lt $f.Count; $i++) {
819:             $got = $row.($f[$i]); $exp = $want[$k][$i]
820:             if (($null -eq $exp -and $null -ne $got) -or ($null -ne $exp -and ($null -eq $got -or [double]$got -ne [double]$exp))) { $badS += "$k $($f[$i]): got '$got', want '$exp'" }
821:         }
822:     }
823:     Check 'SCORE' 'codex-scoreboard -Json over two tasks: every (lineage, purpose) row, lineage totals and the grand total with the right counts, hit rates, verdicts, ratings, medians, tokens' ((@($rateCodes | Where-Object { $_ -ne 0 }).Count -eq 0) -and $sj.Code -eq 0 -and $jr.Count -eq 9 -and $badS.Count -eq 0) ($badS -join ' | ')
