4881: # The members of a review panel (-Panel): the roster walked like Select-RosterReviewer
4882: # without stopping at the first available entry. Every entry whose preflight verdict is
4883: # available (with -SkipPreflight: every entry) runs, unless it is "weighty" and $Purpose is
4884: # light (not in $script:WeightyPurposes) and -All (-PanelAll) is not given, or its engine's
4885: # launch invariant refuses it (wave 23, D4 - with -SkipPreflight too). $Model: as for
4886: # the walk. { Members (object[], roster order, of { Entry; Identity; State 'run'|'skipped';
4887: # Reason ('' when it runs) }); Error ('' or the refusal: nobody runs / no entry for $Model) }.
4888: function Select-PanelMembers {
4889:     param($Roster, $Config, [object[]]$Consults, [string]$Launcher, [hashtable]$LoginCache = $null, [datetime]$UtcNow = [datetime]::UtcNow, [string]$OpenAiBaseUrl = '', [string]$Model = '', [string]$Purpose = '', [switch]$All, [switch]$SkipPreflight, [string]$Engine = '', [hashtable]$EngineLaunchers = $null)
4890:     $members = New-Object System.Collections.Generic.List[object]
4891:     $r = [pscustomobject]@{ Members = [object[]]@(); Error = '' }
4892:     $listing = New-Object System.Collections.Generic.List[string]
4893:     $purposeLabel = if ($Purpose) { $Purpose } else { 'none' }
4894:     foreach ($e in @($Roster.Entries)) {
4895:         $entryEngine = if ($e.PSObject.Properties['Engine'] -and $e.Engine) { [string]$e.Engine } else { 'codex' }
4896:         if ($Engine -and $entryEngine -ne $Engine) { continue }
4897:         $entryLauncher = Get-EngineLauncher -Engine $entryEngine -Launchers $EngineLaunchers -CodexLauncher $Launcher
4898:         $id = Resolve-ReviewerIdentity -Config $Config -Provider $e.Provider -Model $e.Model -OpenAiBaseUrl $OpenAiBaseUrl -Engine $entryEngine -Launcher $entryLauncher
4899:         if ($Model -and $id.Model -cne $Model) { continue }
4900:         $state = 'run'
4901:         $reason = ''
4902:         $block = Get-EngineLaunchBlock -Engine $entryEngine
4903:         if ($block) { $state = 'skipped'; $reason = "refused: $block" }
4904:         elseif (-not $SkipPreflight) {
4905:             $health = $null
4906:             if ($id.Resolved) { $health = Get-EndpointHealth -Consults $Consults -Fingerprint $id.Fingerprint -UtcNow $UtcNow }
4907:             $verdict = Get-PreflightVerdict -Identity $id -Config $Config -Launcher $entryLauncher -Health $health -LoginCache $LoginCache -Anonymous:($e.Auth -eq 'none') -RosterWalk
4908:             if ($verdict.State -ne 'available') { $state = 'skipped'; $reason = $verdict.Reason }
4909:         }
4910:         if ($state -eq 'run' -and $e.Panel -eq 'weighty' -and -not $All -and $script:WeightyPurposes -notcontains $Purpose) {
4911:             $state = 'skipped'
4912:             $reason = "weighty reviewer; purpose $purposeLabel is light (use -PanelAll)"
4913:         }
4914:         $members.Add([pscustomobject]@{ Entry = $e; Identity = $id; State = $state; Reason = $reason })
4915:         $listing.Add("#$($e.Position) $(Format-ReviewerLineage -Provider $id.Provider -Model $id.Model -Engine $entryEngine) ($(if ($state -eq 'run') { 'runs' } else { $reason }))")
4916:     }
4917:     $r.Members = [object[]]$members.ToArray()
4918:     if ($members.Count -eq 0) {
4919:         $all = (@($Roster.Entries) | ForEach-Object { "#$($_.Position) $(if ($_.Model) { Format-ReviewerLineage -Provider $_.Provider -Model $_.Model -Engine $_.Engine } else { "$($_.Provider) (config model)" })" }) -join ', '
4920:         if ($Engine -and -not $Model) {
4921:             $r.Error = "-Engine $($Engine): no entry of the reviewer roster '$($Roster.Path)' uses that engine ($all)"
4922:         } else {
4923:             $r.Error = "-Model $($Model): no entry of the reviewer roster '$($Roster.Path)' resolves to that model ($all); pass -Provider <name> -Model $Model to choose a reviewer outside the roster"
4924:         }
4925:     } elseif (@($members | Where-Object { $_.State -eq 'run' }).Count -eq 0) {
4926:         $r.Error = "no reviewer of the roster '$($Roster.Path)' is available; nothing was started: $($listing.ToArray() -join '; ') (run codex-providers.ps1 for the full picture)"
