5007: # The collab paths an agy panel member's tree check leaves out besides its own handoff files
5008: # (0.4.x wave 21, D7): the task's two stores and the handoffs of the OTHER members of its
5009: # panel ($SiblingNns; none when the panel runs one member at a time), each with its
5010: # Write-TextAtomic temp variant (.<name>.<guid>.tmp in the same directory). The caller passes
5011: # deliberately the union of all other members, not only those that can overlap this one
5012: # (F11-5): an ignored path that did not change hides nothing, and one that changed was written
5013: # by a member running meanwhile - or by this member's reviewer, the documented D7 residual.
5014: # Prefixes relative to the collab root, '/'-separated (Get-CollabSnapshot keys). Everything
5015: # else in the collab root stays monitored (other tasks, state.md, briefs).
5016: function Get-PanelIgnorePrefixes {
5017:     param([string]$Task, [string[]]$SiblingNns = @())
5018:     $nns = @($SiblingNns | Where-Object { $_ })
5019:     $p = New-Object System.Collections.Generic.List[string]
5020:     if ($nns.Count -eq 0) { return , ([string[]]$p.ToArray()) }
5021:     foreach ($store in @('sessions.json', 'findings.json')) { $p.Add("$Task/$store"); $p.Add("$Task/.$store.") }
5022:     foreach ($s in $nns) { $p.Add("$Task/handoffs/$s-"); $p.Add("$Task/handoffs/.$s-") }
5023:     return , ([string[]]$p.ToArray())
5024: }
