5032: # ----------------------------------------------------------------------------- parent thread (lineage)
5033: #
5034: # A thread belongs to one reviewer - reviewer.provider AND reviewer.model, compared field
5035: # by field with ordinal equality (the display string 'lineage' = '<provider> :: <model>'
5036: # is never compared) - on one endpoint (provider_fingerprint). Only a ledger entry written by 0.3.0 or later (it has a
5037: # `reviewer`) whose identity was resolved (non-empty provider_fingerprint) and whose
5038: # `thread` was verified (from the events, or a rollout that contains the consultation
5039: # id) can be a parent - automatically (the newest of this run's lineage) or through
5040: # -Thread. Entries recorded before 0.3.0 have UNKNOWN provenance: never a parent. A
5041: # rollout candidate (thread_candidate) is diagnostic only: never a parent.
5042: 
5043: function Get-EntryFingerprint {
5044:     param($Entry)
5045:     $rev = Get-PropertyValue $Entry 'reviewer' $null
5046:     if ($null -eq $rev) { return '' }
5047:     return [string](Get-PropertyValue $rev 'provider_fingerprint' '')
5048: }
5049: 
5050: # { Provider; Model; Engine; Display } of a 0.3.0+ entry's reviewer ($null for a legacy
5051: # entry). Engine: reviewer.engine, 'codex' when absent (0.3.x entries).
5052: function Get-EntryReviewer {
5053:     param($Entry)
5054:     $rev = Get-PropertyValue $Entry 'reviewer' $null
5055:     if ($null -eq $rev) { return $null }
5056:     $p = [string](Get-PropertyValue $rev 'provider' '')
5057:     $m = [string](Get-PropertyValue $rev 'model' '')
5058:     $e = [string](Get-PropertyValue $rev 'engine' '')
5059:     if (-not $e) { $e = 'codex' }
5060:     return [pscustomobject]@{ Provider = $p; Model = $m; Engine = $e; Display = (Format-ReviewerLineage -Provider $p -Model $m -Engine $e) }
5061: }
5062: 
5063: # Same reviewer: provider and model equal, ordinal (case-sensitive), each on its own - and the
5064: # same engine (an absent one is codex), so a codex thread and an agy thread of the same label
5065: # and model never mix (their fingerprints differ as well).
5066: function Test-SameReviewer {
5067:     param($EntryReviewer, $Identity)
5068:     $idEngine = [string]$Identity.Engine
5069:     if (-not $idEngine) { $idEngine = 'codex' }
5070:     $entryEngine = [string](Get-PropertyValue $EntryReviewer 'Engine' '')
5071:     if (-not $entryEngine) { $entryEngine = 'codex' }
5072:     return ($null -ne $EntryReviewer -and [string]::Equals($EntryReviewer.Provider, [string]$Identity.Provider, [StringComparison]::Ordinal) -and [string]::Equals($EntryReviewer.Model, [string]$Identity.Model, [StringComparison]::Ordinal) -and $entryEngine -eq $idEngine)
5073: }
5074: 
5075: function Format-ShortHash {
5076:     param([string]$Hash)
5077:     if ($Hash.Length -ge 12) { return $Hash.Substring(0, 12) }
5078:     return $Hash
5079: }
5080: 
5081: # The ledger entry that recorded thread $Thread (the newest one) if it can be a parent at
5082: # all: recorded by 0.3.0 or later (it has a `reviewer`) with a resolved identity (a
5083: # provider_fingerprint). { Entry; N; Error }. Used by Select-ParentThread and by the roster
5084: # rule "-Thread fixes the reviewer" (codex-consult.ps1).
5085: function Find-ThreadEntry {
5086:     param([object[]]$Consults, [string]$Thread)
5087:     $r = [pscustomobject]@{ Entry = $null; N = $null; Error = '' }
5088:     $entries = @($Consults | Where-Object { $null -ne $_ })
5089:     $thread = ([string]$Thread).Trim()
5090:     $match = $null
5091:     for ($i = $entries.Count - 1; $i -ge 0; $i--) {
5092:         if ([string](Get-PropertyValue $entries[$i] 'thread' '') -eq $thread) { $match = $entries[$i]; break }
5093:     }
5094:     if (-not $match) {
5095:         $cand = $null
5096:         for ($i = $entries.Count - 1; $i -ge 0; $i--) {
5097:             if ([string](Get-PropertyValue $entries[$i] 'thread_candidate' '') -eq $thread) { $cand = $entries[$i]; break }
5098:         }
5099:         if ($cand) { $r.Error = "thread $thread has unknown provenance: it is only an unverified rollout candidate of consult n=$(Get-PropertyValue $cand 'n' '?') (that rollout did not contain the run's consultation id); use -Mode new" }
5100:         else { $r.Error = "thread $thread has unknown provenance: it is not in this task's ledger; use -Mode new" }
5101:         return $r
5102:     }
5103:     $n = Get-PropertyValue $match 'n' '?'
5104:     if ($null -eq (Get-PropertyValue $match 'reviewer' $null)) {
5105:         $r.Error = "thread $thread has unknown provenance (recorded before 0.3.0); use -Mode new"; return $r
5106:     }
5107:     if (-not (Get-EntryFingerprint $match)) {
5108:         $r.Error = "thread $thread has unknown provenance: consult n=$n ran with an unresolved reviewer identity ($((Get-EntryReviewer $match).Display)); use -Mode new"; return $r
5109:     }
5110:     $r.Entry = $match
5111:     $r.N = $n
5112:     return $r
5113: }
