5115: # { Mode; Parent; ParentN; Note; Error }. $Mode '' = automatic.
5116: function Select-ParentThread {
5117:     param([object[]]$Consults, $Identity, [string]$Mode, [string]$Thread)
5118:     $r = [pscustomobject]@{ Mode = $Mode; Parent = ''; ParentN = $null; Note = ''; Error = '' }
5119:     $entries = @($Consults | Where-Object { $null -ne $_ })
5120:     $lineage = Format-ReviewerLineage -Provider $Identity.Provider -Model $Identity.Model -Engine ([string]$Identity.Engine)
5121:     $unresolvedMsg = "provider identity could not be resolved ($($Identity.Note)); pass -Provider and -Model explicitly, or use -Mode new"
5122:     $driftMsg = { param($t, $n, $fp) "endpoint or protocol of provider $($Identity.Provider) changed since thread $t (consult n=$n recorded provider fingerprint $(Format-ShortHash $fp), now $(Format-ShortHash $Identity.Fingerprint)); start a new thread with -Mode new" }
5123:     $thread = ([string]$Thread).Trim()
5124:     if ($thread) {
5125:         if ($Mode -eq 'new') { $r.Error = '-Thread needs -Mode fork or resume (-Mode new always starts a fresh thread).'; return $r }
5126:         if (-not $Identity.Resolved) { $r.Error = $unresolvedMsg; return $r }
5127:         $found = Find-ThreadEntry -Consults $entries -Thread $thread
5128:         if ($found.Error) { $r.Error = $found.Error; return $r }
5129:         $match = $found.Entry
5130:         $n = $found.N
5131:         $fp = Get-EntryFingerprint $match
5132:         $theirRev = Get-EntryReviewer $match
5133:         $theirs = $theirRev.Display
5134:         if (-not (Test-SameReviewer $theirRev $Identity)) {
5135:             $r.Error = "thread $thread belongs to lineage $theirs (consult n=$n); this run is $lineage. A thread never changes provider or model: use -Mode new, or run as $theirs"; return $r
5136:         }
5137:         if ($fp -ne $Identity.Fingerprint) { $r.Error = (& $driftMsg $thread $n $fp); return $r }
5138:         if (-not $r.Mode) { $r.Mode = 'fork' }
5139:         $r.Parent = $thread
5140:         $r.ParentN = $n
5141:         $r.Note = "-Thread, lineage $lineage (consult n=$n)"
5142:         return $r
5143:     }
5144:     if (-not $Identity.Resolved) {
5145:         if ($Mode -eq 'fork' -or $Mode -eq 'resume') { $r.Error = $unresolvedMsg; return $r }
5146:         $r.Mode = 'new'
5147:         $r.Note = "reviewer identity unresolved, automatic fork/resume is off ($($Identity.Note))"
5148:         return $r
5149:     }
5150:     $parent = $null
5151:     $legacy = 0; $unresolved = 0; $candidates = 0
5152:     $others = New-Object System.Collections.Generic.List[string]
5153:     for ($i = $entries.Count - 1; $i -ge 0; $i--) {
5154:         $c = $entries[$i]
5155:         $t = [string](Get-PropertyValue $c 'thread' '')
5156:         if (-not $t) {
5157:             if ([string](Get-PropertyValue $c 'thread_candidate' '')) { $candidates++ }
5158:             continue
5159:         }
5160:         if ($null -eq (Get-PropertyValue $c 'reviewer' $null)) { $legacy++; continue }
5161:         if (-not (Get-EntryFingerprint $c)) { $unresolved++; continue }
5162:         $cr = Get-EntryReviewer $c
5163:         if (-not (Test-SameReviewer $cr $Identity)) { if (-not $others.Contains($cr.Display)) { $others.Add($cr.Display) }; continue }
5164:         if (-not $parent) { $parent = $c }
5165:     }
5166:     if ($parent) {
5167:         if ($Mode -eq 'new') { return $r }
5168:         $pt = [string]$parent.thread
5169:         $n = Get-PropertyValue $parent 'n' '?'
5170:         $fp = Get-EntryFingerprint $parent
5171:         if ($fp -ne $Identity.Fingerprint) { $r.Error = (& $driftMsg $pt $n $fp); return $r }
5172:         if (-not $r.Mode) { $r.Mode = 'fork' }
5173:         $r.Parent = $pt
5174:         $r.ParentN = $n
5175:         $r.Note = "newest thread of lineage $lineage (consult n=$n)"
5176:         return $r
5177:     }
5178:     $why = New-Object System.Collections.Generic.List[string]
5179:     if ($legacy -gt 0) { $why.Add("$legacy thread(s) recorded before 0.3.0 have unknown provenance and are never automatic parents") }
5180:     if ($others.Count -gt 0) { $why.Add("other lineage(s): $($others -join ', ')") }
5181:     if ($unresolved -gt 0) { $why.Add("$unresolved thread(s) of runs with an unresolved reviewer identity are never parents") }
5182:     if ($candidates -gt 0) { $why.Add("$candidates unverified rollout candidate(s) are never parents") }
5183:     $note = "no thread of lineage $lineage in this task's ledger"
5184:     if ($why.Count -gt 0) { $note += '; ' + ($why.ToArray() -join '; ') }
5185:     if ($Mode -eq 'fork' -or $Mode -eq 'resume') {
5186:         $r.Error = "-Mode $Mode needs a parent thread: $note. Pass -Thread <uuid> of lineage $lineage, or use -Mode new"
5187:         return $r
5188:     }
5189:     $r.Mode = 'new'
5190:     if ($entries.Count -gt 0) { $r.Note = $note }
5191:     return $r
5192: }
