188: function Get-Median {
189:     param([double[]]$Values)
190:     if ($Values.Count -eq 0) { return $null }
191:     $sorted = @($Values | Sort-Object)
192:     $mid = [int][Math]::Floor($sorted.Count / 2)
193:     if ($sorted.Count % 2 -eq 1) { return [double]$sorted[$mid] }
194:     return ([double]$sorted[$mid - 1] + [double]$sorted[$mid]) / 2
195: }
196: 
197: $counters = @('Consults', 'Usable', 'Prose', 'Failed', 'Raised', 'Verified', 'Rejected', 'Wontfix', 'Superseded', 'Open', 'Accept', 'Hold', 'Reject', 'Advise', 'Yes', 'Partly', 'No', 'TokensIn', 'TokensOut')
198: function New-OutRow {
199:     param([string]$Kind, [string]$Lineage, [string]$Purpose, [object[]]$Parts)
200:     $sum = @{}
201:     foreach ($k in $counters) { $sum[$k] = [long]0 }
202:     $walls = New-Object System.Collections.Generic.List[double]
203:     foreach ($a in $Parts) {
204:         foreach ($k in $counters) { $sum[$k] += [long]$a.$k }
205:         foreach ($w in $a.Walls) { $walls.Add($w) }
206:     }
207:     $hit = $null
208:     if (($sum.Verified + $sum.Rejected) -gt 0) { $hit = [int][Math]::Round(100.0 * $sum.Verified / ($sum.Verified + $sum.Rejected), [MidpointRounding]::AwayFromZero) }
209:     $median = Get-Median -Values ([double[]]$walls.ToArray())
210:     return [pscustomobject]@{
211:         kind                = $Kind
212:         lineage             = $Lineage
213:         purpose             = $Purpose
214:         consults            = $sum.Consults
215:         usable              = $sum.Usable
216:         prose               = $sum.Prose
217:         failed              = $sum.Failed
218:         raised              = $sum.Raised
219:         verified            = $sum.Verified
220:         rejected            = $sum.Rejected
221:         wontfix             = $sum.Wontfix
222:         superseded          = $sum.Superseded
223:         open                = $sum.Open
224:         hit_rate            = $hit
225:         verdict_accept      = $sum.Accept
226:         verdict_hold        = $sum.Hold
227:         verdict_reject      = $sum.Reject
228:         verdict_advise      = $sum.Advise
229:         rated_yes           = $sum.Yes
230:         rated_partly        = $sum.Partly
231:         rated_no            = $sum.No
232:         median_wall_seconds = $median
233:         tokens_in           = $sum.TokensIn
234:         tokens_out          = $sum.TokensOut
235:     }
236: }
237: 
238: $all = @($rows.Values)
239: $lineages = @($all | ForEach-Object { $_.Lineage } | Select-Object -Unique | Sort-Object @{ Expression = { $_ -eq 'unknown provenance' } }, @{ Expression = { $_.ToLowerInvariant() } })
240: $out = New-Object System.Collections.Generic.List[object]
241: foreach ($lin in $lineages) {
242:     $mine = @($all | Where-Object { $_.Lineage -eq $lin } | Sort-Object @{ Expression = { $_.Purpose.ToLowerInvariant() } })
243:     foreach ($a in $mine) { $out.Add((New-OutRow -Kind 'purpose' -Lineage $lin -Purpose $a.Purpose -Parts @($a))) }
244:     $out.Add((New-OutRow -Kind 'lineage' -Lineage $lin -Purpose '(total)' -Parts $mine))
245: }
246: if ($all.Count -gt 0) { $out.Add((New-OutRow -Kind 'total' -Lineage '(all)' -Purpose '(total)' -Parts $all)) }
247: 
248: if ($Json) {
249:     Write-Output (ConvertTo-Json -InputObject ([object[]]$out.ToArray()) -Depth 4)
250:     exit 0
251: }
