253: Write-Host "codex-scoreboard: $collabRoot$(if ($Task) { " (task $Task)" } else { " ($($taskDirs.Count) task(s))" })"
254: foreach ($note in $notes) { Write-Host $note -ForegroundColor Yellow }
255: if ($out.Count -eq 0) {
256:     Write-Host 'no consultations recorded.'
257:     exit 0
