4759:     }
4760:     if ($engine -ne 'codex') {
4761:         # An engine keeps its own sign-in: its credential check (agy: `agy models`, or a usable
4762:         # reply on this endpoint within the last 60 minutes - the auth / quota rules below
4763:         # still apply).
