4765:     } else {
4766:         $table = $null
4767:         if ($Config -and $Config.Exists -and $Config.Ok) {
4768:             $pt = Get-ProviderTable -Config $Config -Name $p
4769:             if ($pt.Found) { $table = $pt.Table }
4770:         }
4771:         $cred = Get-ProviderCredential -Name $p -Table $table -Launcher $Launcher -LoginCache $LoginCache -Anonymous:$Anonymous
4772:     }
