4774:     $v.Reason = $cred.Detail
4775:     if ($cred.State -eq 'missing') {
4776:         $v.State = 'unavailable'
4777:         $v.Refusal = "provider $p is not usable: $($cred.Reason); nothing was started (run codex-providers.ps1 for the full picture)"
4778:         $v.Label = "unavailable ($($cred.Reason)) - a real run is refused: $($v.Refusal)"
4779:     } elseif ($cred.State -eq 'unknown') {
4780:         $v.State = 'unknown'
4781:         $v.Refusal = "provider $($p): availability could not be established ($($cred.Reason)); pass -SkipPreflight to launch anyway, or fix the check"
4782:         $v.Label = "unknown ($($cred.Reason)) - a real run is refused: $($v.Refusal)"
4783:     } elseif ($Health -and $Health.Auth) {
4784:         $v.State = 'unavailable'
4785:         $v.Reason = "auth failed $($Health.Auth.When): $($Health.Auth.Message)"
4786:         $v.Preflight = "unavailable: $($v.Reason)"
4787:         $v.Refusal = "provider $p is not usable: the last run on this endpoint was rejected as unauthenticated at $($Health.Auth.When) ($($Health.Auth.Message)); if you rotated the credential, pass -SkipPreflight once"
4788:         $v.Label = "unavailable ($($v.Reason)) - a real run is refused: $($v.Refusal)"
4789:     } elseif ($Health -and $Health.Quota -and $Health.QuotaKnown) {
4790:         $v.State = 'unavailable'
4791:         $v.Reason = "usage limit until $($Health.Quota.RetryAfterIso)"
4792:         $v.Preflight = "unavailable: $($v.Reason)"
4793:         $v.Refusal = "provider $p is not usable: its usage limit (hit at $($Health.Quota.When): $($Health.Quota.Message)) lasts until $($Health.Quota.RetryAfterIso); nothing was started (pass -SkipPreflight to launch anyway)"
4794:         $v.Label = "unavailable ($($v.Reason)) - a real run is refused: $($v.Refusal)"
4795:     } elseif ($RosterWalk -and $Health -and $Health.Quota) {
4796:         $v.State = 'unavailable'
4797:         $v.Reason = "usage limit $($Health.Quota.AgeMinutes) min ago, no reset time given"
4798:         $v.Preflight = "unavailable: $($v.Reason)"
4799:         $v.Refusal = "provider $p is not usable: it hit a usage limit $($Health.Quota.AgeMinutes) min ago ($($Health.Quota.Message)) and named no reset time; nothing was started"
4800:         $v.Label = "unavailable ($($v.Reason)) - a real run is refused: $($v.Refusal)"
4801:     } else {
4802:         $v.Label = "available ($($cred.Detail))"
4803:     }
4804:     return $v
4805: }
