4347: # The ledger's provider_failure of a failed run: { class; code; message (<= 200); when;
4348: # retry_after }. $Texts: the evidence in order of preference (the event-stream error,
4349: # stderr, the bridge outcome); the first that holds a provider error payload wins, else the
4350: # first non-empty. retry_after: the reset time the chosen message names (Get-RetryAfter,
4351: # read from the FULL message before it is cut to 200 characters), ISO with offset, or $null.
4352: function New-ProviderFailure {
4353:     param([string[]]$Texts, [string]$Class = '')
4354:     $chosen = $null
4355:     $chosenRaw = ''
4356:     foreach ($t in @($Texts | Where-Object { $_ -and $_.Trim() })) {
4357:         $p = ConvertFrom-ProviderErrorText -Text $t
4358:         if ($p.Code -or ($t.IndexOf('{"error"') -ge 0)) { $chosen = $p; $chosenRaw = $t; break }
4359:         if (-not $chosen) { $chosen = $p; $chosenRaw = $t }
4360:     }
4361:     if (-not $chosen) { $chosen = [pscustomobject]@{ Code = ''; Message = '' } }
4362:     $msg = [string]$chosen.Message
4363:     $now = Get-Date
4364:     $retryAfter = Get-RetryAfter -Message $msg -Reference ([DateTimeOffset]$now)
4365:     # A gRPC error payload (Google, the agy engine) names its reset time in the details
4366:     # (RetryInfo.retryDelay), outside error.message.
4367:     if ($null -eq $retryAfter -and $chosenRaw -and $chosenRaw -match '(?i)retryDelay') { $retryAfter = Get-RetryAfter -Message $chosenRaw -Reference ([DateTimeOffset]$now) }
4368:     if ($msg.Length -gt 200) { $msg = $msg.Substring(0, 200) }
4369:     return [pscustomobject]@{
4370:         class       = $(if ($Class) { $Class } else { (Get-ProviderFailureClass "$($chosen.Code) $($chosen.Message)") })
4371:         code        = [string]$chosen.Code
4372:         message     = $msg
4373:         when        = (Get-IsoTimestamp $now)
4374:         retry_after = $(if ($null -ne $retryAfter) { Format-OffsetIso $retryAfter } else { $null })
4375:     }
4376: }
